function findNextInspectionDay(start) {
  let found = start;
  for (let day = start; day <= start + 6; day += 1) {
    if (day % 7 === 0) {
      found = day;
      break;
    }
  }
  return found;
}

function findFirstSix(start, end) {
  for (let number = start; number <= end; number += 1) {
    if (number % 6 === 0) return number;
  }
  return 0;
}

function findLimit(price, budget) {
  for (let count = 1; count <= 10; count += 1) {
    if (price * count > budget) return count;
  }
  return 0;
}
